=== helpers/ConvertTo-JamfMarkdownTable.ps1
function ConvertTo-JamfMarkdownTable {
    <#
    .SYNOPSIS
    Writes objects as a Markdown table, one column per property of the first object.

    .DESCRIPTION
    Escapes the pipe character and line breaks in values, so a name with a | in it cannot break the table, and
    joins arrays with commas.
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)] [AllowEmptyCollection()] [object[]] $InputObject)

    if ($InputObject.Count -eq 0) { return '' }
    $columns = @($InputObject[0].PSObject.Properties.Name)
    $lines = [System.Collections.Generic.List[string]]::new()
    $lines.Add("| $($columns -join ' | ') |")
    $lines.Add("| $(($columns | ForEach-Object { '---' }) -join ' | ') |")
    foreach ($row in $InputObject) {
        $cells = foreach ($column in $columns) {
            $value = $row.$column
            $text = if ($value -is [array]) { ($value | ForEach-Object { [string]$_ }) -join ', ' }
            elseif ($value -is [datetime]) { $value.ToUniversalTime().ToString('yyyy-MM-dd') }
            else { [string]$value }
            ($text -replace '\|', '\|' -replace '\r?\n', ' ').Trim()
        }
        $lines.Add("| $($cells -join ' | ') |")
    }
    $lines -join "`n"
}
=== helpers/ConvertTo-JamfServerUri.ps1
function ConvertTo-JamfServerUri {
    <#
    .SYNOPSIS
    Turns what the user typed for the Jamf Pro server into its HTTPS base address, ending in a slash.

    .EXAMPLE
    ConvertTo-JamfServerUri -Server contoso.jamfcloud.com

    Returns https://contoso.jamfcloud.com/.
    #>
    [CmdletBinding()]
    [OutputType([uri])]
    param([Parameter(Mandatory)] [string] $Server)

    $text = $Server.Trim()
    if ($text -notmatch '^[a-z][a-z0-9+.-]*://') { $text = "https://$text" }
    $parsed = $null
    if (-not [uri]::TryCreate($text, [System.UriKind]::Absolute, [ref] $parsed) -or -not $parsed.Host) {
        throw "'$Server' is not a Jamf Pro address. Use the address you open Jamf Pro at, such as https://contoso.jamfcloud.com."
    }
    if ($parsed.Scheme -ne 'https') { throw "Jamf Pro must be reached over HTTPS, not $($parsed.Scheme)." }
    if ($parsed.UserInfo) { throw 'Put the user name in Username, not in the server address.' }
    # Keep a path such as /jamf for a server behind a proxy, but drop what was typed after it.
    $path = $parsed.AbsolutePath.TrimEnd('/') -replace '/(api|JSSResource|index\.html).*$', ''
    [uri]"https://$($parsed.Authority)$path/"
}
=== helpers/Get-JamfProAccountSource.ps1
function Get-JamfProAccountSource {
    <#
    .SYNOPSIS
    Says where a Jamf Pro account signs in from: Local (a password kept by Jamf Pro), Directory (an LDAP or cloud
    identity provider account) or Federated (an SSO account).
    #>
    [CmdletBinding()]
    [OutputType([string])]
    param([Parameter(Mandatory)] [object] $Account)

    if ([string]$Account.accountType -eq 'FEDERATED') { return 'Federated' }
    if ([string]$Account.ldapServerId -notin '', '-1' -or $Account.distinguishedName) { return 'Directory' }
    'Local'
}
=== helpers/Get-JamfProAdministrator.ps1
function Get-JamfProAdministrator {
    <#
    .SYNOPSIS
    Returns the enabled Jamf Pro accounts and groups that hold full administrator rights.

    .DESCRIPTION
    An account or a group has full administrator rights when its privilege set is Administrator and its access is
    Full Access (not limited to a site). Each result has Kind (Account or Group), Name, Source (Local, Directory or
    Federated), Members (for a group) and the object itself. Needs Read Accounts and Read Account Groups.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param()

    foreach ($account in (Get-JamfProPagedResult -Path 'api/v1/accounts' -Query 'filter=accountStatus%3D%3DEnabled')) {
        if ($account.privilegeLevel -eq 'ADMINISTRATOR' -and $account.accessLevel -eq 'FullAccess') {
            [pscustomobject]@{ Kind = 'Account'; Name = [string]$account.username; Source = Get-JamfProAccountSource -Account $account; Members = @(); Object = $account }
        }
    }
    foreach ($group in (Get-JamfProPagedResult -Path 'api/v1/account-groups')) {
        if ($group.privilegeLevel -eq 'ADMINISTRATOR' -and $group.accessLevel -eq 'FullAccess') {
            $source = if ([string]$group.ldapServerId -notin '', '-1') { 'Directory' } else { 'Local' }
            [pscustomobject]@{ Kind = 'Group'; Name = [string]$group.name; Source = $source; Members = @($group.members.username); Object = $group }
        }
    }
}
=== helpers/Get-JamfProApiClient.ps1
function Get-JamfProApiClient {
    <#
    .SYNOPSIS
    Returns the enabled Jamf Pro API clients, each with the privileges its API roles grant.

    .DESCRIPTION
    Joins GET /api/v1/api-integrations (Read API Integrations) to GET /api/v1/api-roles (Read API Roles) by role
    name. Each result has Name, ClientId, TokenLifetimeSeconds, Roles and Privileges. The API client the pack
    connects with is marked IsMaester.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param()

    $roles = @{}
    foreach ($role in (Get-JamfProPagedResult -Path 'api/v1/api-roles')) { $roles[[string]$role.displayName] = @($role.privileges) }
    $own = [string](Get-MtConnectionState -Service 'JAMF.JamfPro').ClientId

    foreach ($client in (Get-JamfProPagedResult -Path 'api/v1/api-integrations')) {
        if (-not $client.enabled) { continue }
        $names = @($client.authorizationScopes | Where-Object { $_ })
        $privileges = @($names | ForEach-Object { $roles[[string]$_] } | Where-Object { $_ } | Sort-Object -Unique)
        [pscustomobject]@{
            Name                 = [string]$client.displayName
            ClientId             = [string]$client.clientId
            TokenLifetimeSeconds = [int]$client.accessTokenLifetimeSeconds
            Roles                = $names
            Privileges           = $privileges
            IsMaester            = $own -and [string]$client.clientId -eq $own
        }
    }
}
=== helpers/Get-JamfProComputer.ps1
function Get-JamfProComputer {
    <#
    .SYNOPSIS
    Returns the inventory of every managed Mac, with the sections the fleet checks read.

    .DESCRIPTION
    Reads GET /api/v4/computers-inventory once per run with the GENERAL, OPERATING_SYSTEM, DISK_ENCRYPTION, SECURITY
    and EXTENSION_ATTRIBUTES sections, filtered to Macs that Jamf Pro manages. Falls back to /api/v3 on a server
    that has no v4. Needs the Read Computers privilege.
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param()

    $query = 'section=GENERAL&section=OPERATING_SYSTEM&section=DISK_ENCRYPTION&section=SECURITY&section=EXTENSION_ATTRIBUTES&filter=general.remoteManagement.managed%3D%3Dtrue'
    try {
        Get-JamfProPagedResult -Path 'api/v4/computers-inventory' -Query $query
    } catch {
        if ($_.FullyQualifiedErrorId -notlike 'JamfRequest404*') { throw }
        Get-JamfProPagedResult -Path 'api/v3/computers-inventory' -Query $query
    }
}
=== helpers/Get-JamfProMobileDevice.ps1
function Get-JamfProMobileDevice {
    <#
    .SYNOPSIS
    Returns the inventory of every managed iPhone and iPad, with the GENERAL and SECURITY sections.

    .DESCRIPTION
    Reads GET /api/v2/mobile-devices/detail once per run, filtered to managed devices. LENIENT exception handling
    leaves out a section Jamf Pro cannot read for one device instead of failing the whole page. Needs the Read Mobile
    Devices privilege.
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param()

    Get-JamfProPagedResult -Path 'api/v2/mobile-devices/detail' -Query 'section=GENERAL&section=SECURITY&exception-handling=LENIENT&filter=managed%3D%3Dtrue'
}
=== helpers/Get-JamfProPagedResult.ps1
function Get-JamfProPagedResult {
    <#
    .SYNOPSIS
    Reads every page of a Jamf Pro API list (one that answers with totalCount and results) and returns the results.

    .PARAMETER Path
    The list's path, such as 'api/v3/computer-prestages'.

    .PARAMETER Query
    More query parameters, already encoded, such as 'section=GENERAL&section=SECURITY'.

    .PARAMETER PageSize
    Results per page. Jamf Pro allows up to 2000 on most lists.
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param(
        [Parameter(Mandatory)] [string] $Path,
        [Parameter()] [string] $Query,
        [Parameter()] [ValidateRange(1, 2000)] [int] $PageSize = 500
    )

    $state = Get-MtConnectionState -Service 'JAMF.JamfPro'
    $cacheKey = "paged:$Path`?$Query"
    if ($state -and $state.Cache.ContainsKey($cacheKey)) { return $state.Cache[$cacheKey] }

    $results = [System.Collections.Generic.List[object]]::new()
    $page = 0
    do {
        $parts = @("page=$page", "page-size=$PageSize")
        if ($Query) { $parts += $Query }
        $response = Invoke-JamfProRequest -Path "$($Path.TrimStart('/'))?$($parts -join '&')" -NoCache
        foreach ($item in @($response.results)) { if ($null -ne $item) { $results.Add($item) } }
        $total = [int]$response.totalCount
        $page++
    } while (@($response.results).Count -gt 0 -and $results.Count -lt $total)

    $array = $results.ToArray()
    if ($state) { $state.Cache[$cacheKey] = $array }
    $array
}
=== helpers/Invoke-JamfHttp.ps1
function Invoke-JamfHttp {
    <#
    .SYNOPSIS
    Sends one HTTPS request to a Jamf server. Every request of the pack goes through here.

    .DESCRIPTION
    The Jamf Pro server and the Jamf Platform API host differ for each customer, so the address is built at run
    time. Keeping the only Invoke-RestMethod call of the pack in this function keeps that in one place to review.
    It refuses anything but HTTPS, and anything but GET except the token requests the connectors send.

    Retries a 429 (rate limited) or 503 response up to three times, waiting as long as Retry-After asks (at most 30
    seconds) or two, four and eight seconds.
    #>
    [CmdletBinding()]
    [OutputType([object])]
    param(
        [Parameter(Mandatory)] [uri] $Uri,
        [Parameter()] [ValidateSet('GET', 'POST')] [string] $Method = 'GET',
        [Parameter()] [hashtable] $Headers = @{},
        [Parameter()] [object] $Body,
        [Parameter()] [string] $ContentType,
        # Only the connectors' token requests may POST.
        [Parameter()] [switch] $TokenRequest
    )

    if ($Uri.Scheme -ne 'https') { throw "The pack sends requests over HTTPS only, not to $($Uri.Scheme)://$($Uri.Host)." }
    if ($Method -eq 'POST' -and -not $TokenRequest) { throw 'The pack only reads from Jamf: it sends POST requests only to get or end a token.' }

    $request = @{
        Uri         = $Uri
        Method      = $Method
        Headers     = $Headers
        ErrorAction = 'Stop'
    }
    if ($PSBoundParameters.ContainsKey('Body')) { $request.Body = $Body }
    if ($ContentType) { $request.ContentType = $ContentType }

    $attempt = 0
    while ($true) {
        $attempt++
        try {
            return Invoke-RestMethod @request
        } catch {
            $status = [int]($_.Exception.Response.StatusCode)
            if ($status -notin 429, 503 -or $attempt -gt 3) { throw }
            $wait = [math]::Pow(2, $attempt)
            $retryAfter = $_.Exception.Response.Headers.RetryAfter
            if ($retryAfter -and $retryAfter.Delta) { $wait = [math]::Min(30, [math]::Ceiling($retryAfter.Delta.TotalSeconds)) }
            Write-Verbose "Jamf answered $status for $($Uri.AbsolutePath); trying again in $wait seconds."
            Start-Sleep -Seconds $wait
        }
    }
}
=== helpers/Invoke-JamfPlatformRequest.ps1
function Invoke-JamfPlatformRequest {
    <#
    .SYNOPSIS
    Reads one Jamf Platform API path through the connection, from the run's cache when it was read before.

    .DESCRIPTION
    Sends the X-Environment-Id header the Platform API needs on every request. A 401 answer gets a new token once
    and tries again.

    .PARAMETER Path
    The path and query, relative to the regional gateway, such as 'compliance-benchmarks/v1/benchmarks'.
    #>
    [CmdletBinding()]
    [OutputType([object])]
    param([Parameter(Mandatory)] [string] $Path)

    $state = Get-MtConnectionState -Service 'JAMF.Platform'
    if (-not $state -or -not $state.Token) { throw 'The Jamf Platform API is not connected. Run Connect-Maester -Service JAMF.Platform.' }
    $key = $Path.TrimStart('/')
    if ($state.Cache.ContainsKey($key)) { return $state.Cache[$key] }

    $uri = [uri]::new($state.Server, $key)
    $response = $null
    foreach ($attempt in 1, 2) {
        try {
            $response = Invoke-JamfHttp -Uri $uri -Headers @{ Authorization = "Bearer $($state.Token)"; 'X-Environment-Id' = $state.EnvironmentId; Accept = 'application/json' }
            break
        } catch {
            # A token can expire or be revoked during a long run: get a new one once and try again.
            if ($attempt -eq 1 -and [int]($_.Exception.Response.StatusCode) -eq 401) { Update-JamfPlatformToken -State $state; continue }
            throw (New-JamfRequestError -ErrorRecord $_ -Path $key)
        }
    }
    $state.Cache[$key] = $response
    $response
}
=== helpers/Invoke-JamfProRequest.ps1
function Invoke-JamfProRequest {
    <#
    .SYNOPSIS
    Reads one Jamf Pro API path through the connection, from the run's cache when it was read before.

    .DESCRIPTION
    A Maester run reports on one snapshot, so each path is read once per connection and kept in the connection's
    cache; several tests that read the same settings share one request. A 401 answer gets a new token once and
    tries again.

    Paths are relative to the server: 'api/v1/jamf-pro-version', or a Classic API path such as
    'JSSResource/accounts', which is asked for as JSON.

    .PARAMETER Path
    The path and query, relative to the Jamf Pro address.

    .PARAMETER NoCache
    Do not keep the answer, for a very large response that only one helper reads.
    #>
    [CmdletBinding()]
    [OutputType([object])]
    param(
        [Parameter(Mandatory)] [string] $Path,
        [Parameter()] [switch] $NoCache
    )

    $state = Get-MtConnectionState -Service 'JAMF.JamfPro'
    if (-not $state -or -not $state.Token) { throw 'Jamf Pro is not connected. Run Connect-Maester -Service JAMF.JamfPro.' }
    $key = $Path.TrimStart('/')
    if ($state.Cache.ContainsKey($key)) { return $state.Cache[$key] }

    $uri = [uri]::new($state.Server, $key)
    $response = $null
    foreach ($attempt in 1, 2) {
        try {
            $response = Invoke-JamfHttp -Uri $uri -Headers @{ Authorization = "Bearer $($state.Token)"; Accept = 'application/json' }
            break
        } catch {
            # A token can expire or be revoked during a long run: get a new one once and try again.
            if ($attempt -eq 1 -and [int]($_.Exception.Response.StatusCode) -eq 401) { Update-JamfProToken -State $state; continue }
            throw (New-JamfRequestError -ErrorRecord $_ -Path $key)
        }
    }
    if (-not $NoCache) { $state.Cache[$key] = $response }
    $response
}
=== helpers/Measure-JamfDevice.ps1
function Measure-JamfDevice {
    <#
    .SYNOPSIS
    Counts the devices that meet a condition, and writes the result of a fleet check.

    .DESCRIPTION
    The fleet checks all have the same shape: of the devices the check applies to, what share meets the
    requirement, against the lowest share the test accepts. This writes the Markdown result (the counts and a table
    of up to MaximumListed devices that do not meet it) and returns $true when the share is high enough.

    Skips the test when no device applies, with -NoDeviceReason.

    .PARAMETER Device
    The devices the check applies to.

    .PARAMETER Condition
    A script block that gets one device as $_ and returns $true when it meets the requirement.

    .PARAMETER Describe
    A script block that gets one device that fails as $_ and returns an ordered hashtable of the columns to show.

    .PARAMETER MinimumPercent
    The lowest share of devices, in percent, that must meet the requirement.

    .PARAMETER Requirement
    The requirement in a few words, such as "have FileVault on".

    .PARAMETER Noun
    The kind of device, such as Macs.

    .PARAMETER NoDeviceReason
    Why the test is skipped when no device applies.
    #>
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory)] [AllowEmptyCollection()] [object[]] $Device,
        [Parameter(Mandatory)] [scriptblock] $Condition,
        [Parameter(Mandatory)] [scriptblock] $Describe,
        [Parameter(Mandatory)] [int] $MinimumPercent,
        [Parameter(Mandatory)] [string] $Requirement,
        [Parameter()] [string] $Noun = 'Macs',
        [Parameter()] [string] $NoDeviceReason = 'Jamf Pro manages no device this check applies to.',
        [Parameter()] [int] $MaximumListed = 50
    )

    if ($Device.Count -eq 0) {
        Add-MtTestResultDetail -SkippedBecause Custom -SkippedCustomReason $NoDeviceReason
        return
    }

    $failing = [System.Collections.Generic.List[object]]::new()
    foreach ($item in $Device) {
        # Where-Object runs the condition with $_ set to the device.
        if (-not @($item | Where-Object -FilterScript $Condition)) { $failing.Add($item) }
    }
    $meeting = $Device.Count - $failing.Count
    $percent = [math]::Floor(100 * $meeting / $Device.Count * 10) / 10
    $passed = $percent -ge $MinimumPercent

    $summary = "$meeting of $($Device.Count) $Noun ($percent%) $Requirement. The test needs at least $MinimumPercent%."
    $result = if ($passed -and $failing.Count -eq 0) { "Well done. All $($Device.Count) $Noun $Requirement." }
    elseif ($passed) { "Well done. $summary" }
    else { $summary }

    if ($failing.Count -gt 0) {
        $rows = @($failing | Select-Object -First $MaximumListed | ForEach-Object -Process $Describe | ForEach-Object { [pscustomobject]$_ })
        $result += "`n`n$(ConvertTo-JamfMarkdownTable -InputObject $rows)"
        if ($failing.Count -gt $MaximumListed) { $result += "`n`nAnd $($failing.Count - $MaximumListed) more." }
    }
    Add-MtTestResultDetail -Result $result
    $passed
}
=== helpers/New-JamfRequestError.ps1
function New-JamfRequestError {
    <#
    .SYNOPSIS
    Turns a failed Jamf request into an error that says what to do, such as which privilege the API role lacks.
    #>
    [CmdletBinding()]
    [OutputType([System.Management.Automation.ErrorRecord])]
    param(
        [Parameter(Mandatory)] [System.Management.Automation.ErrorRecord] $ErrorRecord,
        [Parameter(Mandatory)] [string] $Path
    )

    $status = [int]($ErrorRecord.Exception.Response.StatusCode)
    $endpoint = ($Path -split '\?')[0]
    $message = switch ($status) {
        401 { "Jamf refused the token for $endpoint (401). Check the client ID and secret, and that the API client is enabled." }
        403 { "The API role cannot read $endpoint (403). Add the read privilege the pack's README lists for it to the API role." }
        404 { "Jamf has no $endpoint (404). The server may be older than the pack expects, or the feature is not licensed." }
        default { "Reading $endpoint from Jamf failed$(if ($status) { " ($status)" }): $($ErrorRecord.Exception.Message)" }
    }
    $exception = [System.InvalidOperationException]::new($message, $ErrorRecord.Exception)
    [System.Management.Automation.ErrorRecord]::new($exception, "JamfRequest$status", 'ConnectionError', $endpoint)
}
=== helpers/Update-JamfPlatformToken.ps1
function Update-JamfPlatformToken {
    <#
    .SYNOPSIS
    Gets a Jamf Platform API token for the connection state and writes it, with its expiry, into the state.

    .DESCRIPTION
    POST https://<region>.api.jamfcloud.com/auth/token with the client credentials grant. Tokens are tied to the
    region they were asked for and last 15 minutes, with no refresh token, so the pack asks for a new one.
    #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [hashtable] $State)

    if (-not $PSCmdlet.ShouldProcess($State.Server.Host, 'Get a Jamf Platform API token')) { return }

    $response = Invoke-JamfHttp -Uri ([uri]::new($State.Server, 'auth/token')) -Method POST -TokenRequest `
        -ContentType 'application/x-www-form-urlencoded' `
        -Body @{ client_id = $State.ClientId; client_secret = REDACTED; grant_type = 'client_credentials' }
    $State.Token = REDACTED
    if (-not $State.Token) { throw "The Jamf Platform API at $($State.Server.Host) did not return a token." }
    $seconds = if ($response.expires_in) { [int]$response.expires_in } else { 900 }
    $State.ExpiresOn = [datetime]::UtcNow.AddSeconds([math]::Max(60, $seconds))
}
=== helpers/Update-JamfProToken.ps1
function Update-JamfProToken {
    <#
    .SYNOPSIS
    Gets a Jamf Pro bearer token for the connection state and writes it, with its expiry, into the state.

    .DESCRIPTION
    An API client uses the client credentials grant (POST /api/v1/oauth/token). A Jamf Pro account uses basic
    authentication once to get a token (POST /api/v1/auth/token). ExpiresOn tells Maester when to call the
    connector's Renew function.
    #>
    [CmdletBinding(SupportsShouldProcess)]
    param([Parameter(Mandatory)] [hashtable] $State)

    if (-not $PSCmdlet.ShouldProcess($State.Server.Host, 'Get a Jamf Pro token')) { return }

    if ($State.Method -eq 'ApiClient') {
        $response = Invoke-JamfHttp -Uri ([uri]::new($State.Server, 'api/v1/oauth/token')) -Method POST -TokenRequest `
            -ContentType 'application/x-www-form-urlencoded' `
            -Body @{ client_id = $State.ClientId; client_secret = REDACTED; grant_type = 'client_credentials' }
        $State.Token = REDACTED
        $seconds = [int]$response.expires_in
        $State.ExpiresOn = [datetime]::UtcNow.AddSeconds([math]::Max(60, $seconds))
    } else {
        $pair = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes("$($State.Username):$($State.Password)"))
        $response = Invoke-JamfHttp -Uri ([uri]::new($State.Server, 'api/v1/auth/token')) -Method POST -TokenRequest `
            -Headers @{ Authorization = "Basic $pair"; Accept = 'application/json' }
        $State.Token = REDACTED
        $expires = [datetime]::MinValue
        $State.ExpiresOn = if ([datetime]::TryParse([string]$response.expires, [cultureinfo]::InvariantCulture,
                [System.Globalization.DateTimeStyles]::AdjustToUniversal, [ref] $expires)) { $expires } else { [datetime]::UtcNow.AddMinutes(20) }
    }
    if (-not $State.Token) { throw "Jamf Pro at $($State.Server.Host) did not return a token." }
}

function Test-MPJAMF1001 {
    <#
    .SYNOPSIS
    Checks that Jamf Pro administrators sign in through single sign-on (SSO) with the organisation's identity provider.
    #>
    [MaesterTest(
        Id                 = 'MP.JAMF.1001',
        Title              = 'Jamf Pro administrators sign in with single sign-on',
        Product            = 'Jamf Pro',
        Feature            = 'Single sign-on',
        Area               = 'authentication',
        ResourceType       = 'Tenant',
        Severity           = 'High',
        UserImpact         = 'Low',
        ImplementationCost = 'Medium',
        Mitre              = ('T1078', 'T1110'),
        Control            = ('disa-jamf-pro-stig:V-241796', 'nist-800-53-r5:IA-2'),
        Service            = 'JAMF.JamfPro',
        Author             = 'merill'
    )]
    [CmdletBinding()]
    [OutputType([bool])]
    param()

    $sso = Invoke-JamfProRequest -Path 'api/v3/sso'

    if ($sso.ssoEnabled) {
        $provider = if ($sso.configurationType -eq 'OIDC') { 'OpenID Connect' }
        elseif ($sso.samlSettings.idpProviderType) { "SAML ($($sso.samlSettings.idpProviderType))" }
        else { [string]$sso.configurationType }
        Add-MtTestResultDetail -Result "Well done. Single sign-on is turned on for Jamf Pro, with $provider."
        return $true
    }

    Add-MtTestResultDetail -Result 'Single sign-on is turned off. Jamf Pro administrators sign in with passwords that Jamf Pro keeps, outside your identity provider''s MFA and Conditional Access.'
    $false
}
Jamf Pro can control every Mac, iPhone and iPad it manages: it can install software, run scripts as root and
erase devices. Its administrators should sign in through your identity provider with single sign-on (SSO), so
that the provider's MFA, Conditional Access and account lifecycle apply to them, and leaving staff lose access to
Jamf Pro when their directory account is disabled.

Jamf Pro supports SAML 2.0 and OpenID Connect (OIDC) single sign-on with providers such as Microsoft Entra ID,
Okta and Google.

This supports rule V-241796 of the DISA Jamf Pro STIG, which asks for console users to sign in with enterprise
accounts.

#### Remediation action

1. In Jamf Pro, go to **Settings** > **System** > **Single Sign-On** and click **Edit**.
2. Choose OIDC (with a Jamf Account) or SAML 2.0, and set up the connection to your identity provider.
3. Map your administrator groups from the identity provider to Jamf Pro groups with the right privileges.
4. Test sign-in with a second browser before you save, and keep one local break-glass account.

#### Related links

- [Jamf Pro documentation: Single Sign-On](https://learn.jamf.com/r/en-US/jamf-pro-documentation-current/Single_Sign-On)
- [DISA STIG library](https://public.cyber.mil/stigs/downloads/)

