            $cache = New-IdentitySpecClientCache -Roles $roles -Clients @(@{ Name = 'CI pipeline'; Roles = @('Deploy') })
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1008 -Cache $cache
            $row.Result | Should -Be 'Investigate'
            $row.ResultDetail.TestResult | Should -Match '\| CI pipeline \| id-CI pipeline \| Deploy \| 3 \|'
        }

