            (Invoke-JamfSpecTest -Id MP.JAMF.1008 -Cache $cache -Parameter @{ AllowedApiClients = @('CI pipeline') }).Result | Should -Be 'Passed'
        }
    }

    Context 'MP.JAMF.1009 API client token lifetime' {
        It 'passes with short-lived tokens' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Read Only' = @('Read Computers') } -Clients @(@{ Name = 'Inventory sync'; Roles = @('Read Only'); Lifetime = 1800 })
            (Invoke-JamfSpecTest -Id MP.JAMF.1009 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'fails with a long-lived token' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Read Only' = @('Read Computers') } -Clients @(@{ Name = 'Reporting'; Roles = @('Read Only'); Lifetime = 7200 })
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1009 -Cache $cache
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match '120 minutes'
        }

        It 'takes the limit from MaximumTokenLifetimeSeconds' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Read Only' = @('Read Computers') } -Clients @(@{ Name = 'Reporting'; Roles = @('Read Only'); Lifetime = 7200 })
            (Invoke-JamfSpecTest -Id MP.JAMF.1009 -Cache $cache -Parameter @{ MaximumTokenLifetimeSeconds = 7200 }).Result | Should -Be 'Passed'
        }

        It 'is skipped when there is no enabled client' {
            $cache = New-IdentitySpecClientCache -Roles @{ 'Read Only' = @('Read Computers') } -Clients @(@{ Name = 'Old'; Roles = @('Read Only'); Enabled = $false })
            (Invoke-JamfSpecTest -Id MP.JAMF.1009 -Cache $cache).Result | Should -Be 'Skipped'
        }
    }

    Context 'MP.JAMF.1010 supported version' {
        It 'passes on Jamf Cloud whatever the version' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = '11.20.0-t1700000000' }; 'api/v1/cloud-information' = @{ cloudInstance = $true } }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1010 -Cache $cache
            $row.Result | Should -Be 'Passed'
            $row.ResultDetail.TestResult | Should -Match 'Jamf Cloud'
        }

        It 'passes on a hosted server at or above the minimum' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = '11.33.1-t1761234567' }; 'api/v1/cloud-information' = @{ cloudInstance = $false } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1010 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'fails on a hosted server below the minimum' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = '11.9.2-t1700000000' }; 'api/v1/cloud-information' = @{ cloudInstance = $false } }
