        }

        It 'takes the minimum from MinimumVersion' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = '11.25.0' }; 'api/v1/cloud-information' = @{ cloudInstance = $false } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1010 -Cache $cache -Parameter @{ MinimumVersion = '11.20' }).Result | Should -Be 'Passed'
        }

        It 'asks for a review when the version cannot be read' {
            $cache = @{ 'api/v1/jamf-pro-version' = @{ version = 'unknown' }; 'api/v1/cloud-information' = @{ cloudInstance = $false } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1010 -Cache $cache).Result | Should -Be 'Investigate'
        }
    }

    Context 'MP.JAMF.1011 sign-in notice' {
        It 'passes with a disclaimer that has text' {
            $cache = @{ 'api/v1/login-customization' = @{ includeCustomDisclaimer = $true; disclaimerHeading = 'Notice'; disclaimerMainText = 'Authorised use only.'; actionText = 'Accept' } }
            (Invoke-JamfSpecTest -Id MP.JAMF.1011 -Cache $cache).Result | Should -Be 'Passed'
        }

        It 'fails when the disclaimer is off' {
