# Tests of the identity, administrator and API client checks (MP.JAMF.1002 to MP.JAMF.1011).
Describe 'Jamf Pro pack: identity, administrators and API clients' {
    BeforeAll {
        . "$PSScriptRoot/Fixture.ps1"
        Import-JamfSpecMaester

        $script:GroupsKey = 'paged:api/v1/account-groups?'
        $script:RolesKey = 'paged:api/v1/api-roles?'
        $script:ClientsKey = 'paged:api/v1/api-integrations?'

        function New-IdentitySpecAccount {
            <# One Jamf Pro account in the shape GET /api/v1/accounts returns. #>
            param(
                [string] $Username = 'admin',
                [string] $Privilege = 'ADMINISTRATOR',
                [string] $Access = 'FullAccess',
                [string] $Type = 'DEFAULT',
                [int] $LdapServerId = -1,
                [int] $PasswordAgeDays = 10,
                [switch] $NoPasswordChange
            )
            $account = @{
                id = [string](Get-Random -Maximum 100000); username = $Username; realname = $Username
                ldapServerId = $LdapServerId; siteId = -1; accessLevel = $Access; privilegeLevel = $Privilege
                accountStatus = 'Enabled'; accountType = $Type; changePasswordOnNextLogin = $false; failedLoginAttempts = 0
            }
            if (-not $NoPasswordChange) { $account.lastPasswordChange = [datetime]::UtcNow.AddDays(-$PasswordAgeDays).ToString('o') }
            $account
        }

        function New-IdentitySpecGroup {
            <# One Jamf Pro account group in the shape GET /api/v1/account-groups returns. #>
            param([string] $Name = 'Admins', [string[]] $Members = @(), [string] $LdapServerId = '-1', [string] $Privilege = 'ADMINISTRATOR')
            @{
                id = [string](Get-Random -Maximum 100000); name = $Name; accessLevel = 'FullAccess'; privilegeLevel = $Privilege
                siteId = '-1'; ldapServerId = $LdapServerId
                members = @($Members | ForEach-Object { @{ id = [string](Get-Random -Maximum 100000); username = $_ } })
            }
        }

        function New-IdentitySpecClientCache {
            <#
            The API roles and clients caches. -Clients is a list of hashtables with Name, Roles, and optionally
            ClientId, Lifetime and Enabled; -Roles maps role names to privileges.
            #>
            param([hashtable] $Roles, [object[]] $Clients)
            $i = 0
            @{
                $script:RolesKey   = @($Roles.Keys | ForEach-Object { @{ id = [string](++$i); displayName = $_; privileges = @($Roles[$_]) } })
                $script:ClientsKey = @($Clients | ForEach-Object {
                        @{
                            id = ++$i; displayName = $_.Name; clientId = if ($_.ClientId) { $_.ClientId } else { "id-$($_.Name)" }
                            enabled = if ($_.ContainsKey('Enabled')) { $_.Enabled } else { $true }
                            authorizationScopes = @($_.Roles); appType = 'CLIENT_CREDENTIALS'
                            accessTokenLifetimeSeconds = if ($_.Lifetime) { $_.Lifetime } else { 300 }
                        }
                    })
            }
        }

        $script:SsoOn = @{ ssoEnabled = $true; ssoBypassAllowed = $false; configurationType = 'SAML'; samlSettings = @{ idpProviderType = 'AZURE'; metadataSource = 'URL'; idpUrl = 'https://login.microsoftonline.com/tenant/federationmetadata/2007-06/federationmetadata.xml' } }
    }

    Context 'the new files' {
        It 'are valid native tests with a guide: <_>' -ForEach @('1002', '1003', '1004', '1005', '1006', '1007', '1008', '1009', '1010', '1011') {
            $file = Join-Path $script:PackRoot "tests/Test.MP.JAMF.$_.ps1"
            $test = Get-MtTest -Path $file
            $test.Errors | Should -BeNullOrEmpty
            $test.IsValid | Should -BeTrue
        }
    }

    Context 'MP.JAMF.1002 single sign-on bypass' {
        It 'passes when users cannot bypass SSO' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1002 -Cache @{ 'api/v3/sso' = $script:SsoOn }
            $row.Result | Should -Be 'Passed'
            $row.Benchmark.Requirement | Should -Be 'V-241797'
        }

        It 'fails when the bypass is allowed' {
            $sso = $script:SsoOn.Clone(); $sso.ssoBypassAllowed = $true
            (Invoke-JamfSpecTest -Id MP.JAMF.1002 -Cache @{ 'api/v3/sso' = $sso }).Result | Should -Be 'Failed'
        }

        It 'is not applicable when SSO is off' {
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1002 -Cache @{ 'api/v3/sso' = @{ ssoEnabled = $false; ssoBypassAllowed = $true } }
            $row.Result | Should -Be 'Skipped'
            $row.ReasonCode | Should -Be 'NotApplicable'
        }
    }

    Context 'MP.JAMF.1003 SAML identity provider over HTTPS' {
