        }

        It 'fails with an http metadata URL' {
            $sso = @{ ssoEnabled = $true; configurationType = 'OIDC_WITH_SAML'; samlSettings = @{ idpProviderType = 'OKTA'; metadataSource = 'URL'; idpUrl = 'http://idp.contoso.com/metadata' } }
            $row = Invoke-JamfSpecTest -Id MP.JAMF.1003 -Cache @{ 'api/v3/sso' = $sso }
            $row.Result | Should -Be 'Failed'
            $row.ResultDetail.TestResult | Should -Match 'http://idp.contoso.com'
        }

        It 'asks for a review when the metadata was uploaded as a file' {
