            $row.ReasonCode | Should -Be 'NotApplicable'
        }

        It 'is not applicable when SSO is off' {
            (Invoke-JamfSpecTest -Id MP.JAMF.1003 -Cache @{ 'api/v3/sso' = @{ ssoEnabled = $false; configurationType = 'SAML' } }).Result | Should -Be 'Skipped'
        }
