        }

        It 'takes the limit from MaximumLocalAccounts' {
            $cache = @{
                'api/v3/sso'                 = $script:SsoOn
                (Get-JamfSpecQuery Accounts) = @((New-IdentitySpecAccount -Username 'admin'))
            }
