            $cache = New-IdentitySpecClientCache -Roles $roles -Clients @(@{ Name = 'Help desk'; Roles = @('Keys') }, @{ Name = 'MDM tool'; ClientId = 'abc-123'; Roles = @('Lock') })
            (Invoke-JamfSpecTest -Id MP.JAMF.1007 -Cache $cache -Parameter @{ AllowedApiClients = @('Help desk', 'abc-123') }).Result | Should -Be 'Passed'
        }
    }

    Context 'MP.JAMF.1008 API clients that can change Jamf Pro' {
